mapper.select:
SELECT r.id, r.reimbursement_no, r.status, r.title, r.reason, r.reimburser_id, r.reimburser_name, r.reimburser_no, r.department_id, r.department_name, r.department_no, r.company_id, r.company_name, r.company_no, r.business_type_id, r.business_type_name, r.subsidy_amount, r.create_time FROM reimbursement r
AND r.deleted = 0
AND r.reimbursement_no = #{query.reimbursementNo}
AND r.title LIKE CONCAT('%', #{query.title}, '%')
AND r.reason LIKE CONCAT('%', #{query.reason}, '%')
AND r.company_id = #{query.companyId}
AND r.department_id = #{query.departmentId}
AND r.reimburser_id = #{query.reimburserId}
AND r.business_type_id = #{query.businessTypeId}
ORDER BY r.create_time DESC
